/* Old OnePage addresses keep working. A OnePage is served at storelib.me/{address}, and a creator can change that address in the editor; the old one then answered 404, although it may already be in a bio, a QR code or a post. This keeps each address a page leaves behind in a new table, onepage_slug_history, written by a trigger on onepages when the address changes (lower case, the page's id, when), and the page and the old links (lib/onepage/resolve-address.ts) send a visitor from an old address to the one the page has now, with a permanent redirect. An address another page holds now is always that page's. Server only: row level security on and no policy, so only the service role reads it. The trigger never stops a save: if it cannot write, it warns and the save goes on. Changes no row. Nothing where there is no onepages table. Needs nothing else. Until it runs, a page's old address is not followed, as before; a creator's old username is followed either way. */
DO $$ BEGIN IF to_regclass('public.onepages') IS NULL THEN RAISE NOTICE 'part 58: there is no onepages table, nothing to do.'; RETURN; END IF; CREATE TABLE IF NOT EXISTS public.onepage_slug_history (id uuid PRIMARY KEY DEFAULT gen_random_uuid(), onepage_id uuid NOT NULL REFERENCES public.onepages(id) ON DELETE CASCADE, old_slug text NOT NULL, new_slug text, changed_at timestamptz NOT NULL DEFAULT now()); CREATE INDEX IF NOT EXISTS onepage_slug_history_old_slug_idx ON public.onepage_slug_history (old_slug, changed_at DESC); ALTER TABLE public.onepage_slug_history ENABLE ROW LEVEL SECURITY; REVOKE ALL ON public.onepage_slug_history FROM anon, authenticated; END $$;
CREATE OR REPLACE FUNCTION public.onepages_keep_old_slug() RETURNS trigger LANGUAGE plpgsql SECURITY DEFINER SET search_path = public AS $fn$ BEGIN IF OLD.slug IS NOT NULL AND btrim(OLD.slug) <> '' AND lower(OLD.slug) IS DISTINCT FROM lower(NEW.slug) THEN INSERT INTO public.onepage_slug_history (onepage_id, old_slug, new_slug) VALUES (OLD.id, lower(btrim(OLD.slug)), lower(btrim(NEW.slug))); END IF; RETURN NEW; EXCEPTION WHEN OTHERS THEN RAISE WARNING 'onepages_keep_old_slug skipped for %: %', OLD.id, SQLERRM; RETURN NEW; END $fn$;
REVOKE ALL ON FUNCTION public.onepages_keep_old_slug() FROM PUBLIC, anon, authenticated;
DO $$ BEGIN IF to_regclass('public.onepages') IS NULL THEN RETURN; END IF; DROP TRIGGER IF EXISTS onepages_keep_old_slug ON public.onepages; CREATE TRIGGER onepages_keep_old_slug AFTER UPDATE OF slug ON public.onepages FOR EACH ROW EXECUTE FUNCTION public.onepages_keep_old_slug(); END $$;
notify pgrst, 'reload schema';
